export function f360UserPlan420(rows:readonly BuildingComponent[],leaf:Leaf420|undefined,patch:Leaf420|undefined){const readyNumbers:string[]=[],held:BuildingComponent[]=[];for(const s of SPECS420 as readonly any[])if(ready420(s,rows,leaf,patch)){readyNumbers.push(s.number);for(const c of rows)if(s.heldPartIds.includes(c.partId))held.push(c);}return{readyNumbers,held};}
